/**
 ******************************************************************************
 * @file    : tfcard_main.c
 * @brief   : TF card (SDMMC1) bare-metal LRUN verification app.
 *
 * Purpose: Replicate ALIENTEK Projects/38_SD_Card functionality (SD card init,
 *          card info dump, sector-0 read test) running as an LRUN application
 *          launched by our custom FSBL (same road as camera diag9f).
 *
 * Key differences vs stock 38_SD_Card/main.c (all verified in diag9f):
 *   1. D-Cache stays DISABLED (LTDC framebuffer / SD IDMA coherency).
 *   2. __enable_irq() forced after FSBL hand-off (same as diag9f).
 *   3. Static 512B buffer instead of alientek memory pool (no HyperRAM).
 *   4. Stage markers on UART for fault localization.
 ******************************************************************************
 */
/* Includes ------------------------------------------------------------------*/
#include "main.h"

/* Private includes ----------------------------------------------------------*/
#include "./LED/led.h"
#include "./KEY/key.h"
#include "./UART/uart.h"
#include "./RGBLCD/rgblcd.h"
#include "./SD_CARD/sd_card.h"

/* Private variables ---------------------------------------------------------*/

DMA2D_HandleTypeDef hdma2d;

LTDC_HandleTypeDef hltdc;

SD_HandleTypeDef hsd1;

UART_HandleTypeDef huart1;

/* Static SD read buffer (replaces alientek malloc pool) */
static uint8_t g_sd_buf[512];

/* USER CODE BEGIN 0 */
/* Early UART byte output (USART1 direct register access).
 * Works before uart_init() because the FSBL configures USART1=HSI 115200
 * before jumping (same approach as camera diag9f). */
static void dbg_putc(char c)
{
  USART_TypeDef *u = USART1;
  while ((u->ISR & 0x80U) == 0U) { }
  u->TDR = (uint32_t)c;
}

static void dbg_puts(const char *s)
{
  while (*s) { dbg_putc(*s++); }
}
/* USER CODE END 0 */

/* Private function prototypes -----------------------------------------------*/
static void MX_GPIO_Init(void);
static void MX_DMA2D_Init(void);
static void MX_LTDC_Init(void);
static void MX_SDMMC1_SD_Init(void);
static void MX_USART1_UART_Init(void);
static void SystemIsolation_Config(void);
static void show_sdcard_info(void);
static void sd_read_test(void);

/**
  * @brief  The application entry point.
  * @retval int
  */
int main(void)
{
  /* USER CODE BEGIN 1 */
  uint8_t t = 0;
  uint8_t key;
  /* USER CODE END 1 */

  /* Enable the CPU Cache */
  SCB_EnableICache();

  /* D-Cache deliberately NOT enabled:
   * LTDC DMA reads the framebuffer and SDMMC IDMA transfer coherency are
   * simpler without it (same decision as camera diag9f). */

  /* MCU Configuration--------------------------------------------------------*/
  SystemCoreClockUpdate();
  HAL_Init();
  __enable_irq();          /* force global IRQ on after FSBL hand-off */
  dbg_puts("[A] tfcard main entry\r\n");

  SystemCoreClockUpdate();

  /* Initialize all configured peripherals */
  MX_GPIO_Init();
  MX_DMA2D_Init();
  MX_LTDC_Init();
  MX_SDMMC1_SD_Init();
  MX_USART1_UART_Init();
  SystemIsolation_Config();
  dbg_puts("[B] periph init done\r\n");

  /* USER CODE BEGIN 2 */
  led_init();             /* 初始化LED */
  key_init();             /* 初始化按键 */
  uart_init(115200);      /* 初始化串口 */
  rgblcd_init();          /* 初始化RGB LCD */
  dbg_puts("[C] BSP init done\r\n");

  rgblcd_show_string(30, 50, 200, 16, 16, "STM32", RED);
  rgblcd_show_string(30, 70, 200, 16, 16, "SD Card TEST", RED);
  rgblcd_show_string(30, 90, 200, 16, 16, "ATOM@ALIENTEK", RED);

  while (sd_card_init())  /* 初始化SD卡 */
  {
    rgblcd_show_string(30, 110, 200, 16, 16, "SD Card Error!", RED);
    HAL_Delay(500);
    rgblcd_show_string(30, 110, 200, 16, 16, "Please Check! ", RED);
    HAL_Delay(500);
    LED0_TOGGLE();
  }
  rgblcd_show_string(30, 110, 200, 16, 16, "SD Card OK!   ", RED);

  /* 显示SD卡信息 */
  show_sdcard_info();
  /* USER CODE END 2 */

  /* Infinite loop */
  while (1)
  {
    key = key_scan(0);
    if (key == KEY0_PRES)
    {
      /* SD卡读测试 */
      sd_read_test();
    }

    if (++t == 20)
    {
      t = 0;
      LED0_TOGGLE();
    }

    HAL_Delay(10);
  }
}

