static void dbg_puts(const char *s)
{
  while (*s) { dbg_putc(*s++); }
}

/* Decimal print (no libc dependency) */
static void dbg_print_u32(uint32_t v)
{
  char buf[12];
  int i = 0;
  if (v == 0U) { dbg_putc('0'); return; }
  while (v != 0U)
  {
    buf[i++] = (char)('0' + (v % 10U));
    v /= 10U;
  }
  while (i > 0) { dbg_putc(buf[--i]); }
}

/* Hex byte print: HH */
static void dbg_print_hex8(uint8_t v)
{
  static const char hex[] = "0123456789ABCDEF";
  dbg_putc(hex[(v >> 4) & 0x0F]);
  dbg_putc(hex[v & 0x0F]);
}

