/* Enable the SDMMC peripheral clock (RCC AHB5ENR.SDMMCxEN) BEFORE
 * touching any SDMMC register -- without the clock the register reads
 * return 0 and the cmd/data status loops would hang the boot.
 * This is the verify-18:49 baseline pattern: with it, NuttShell came
 * up and AHB5ENR read back bit8=1 on real HW.  (The AHB5ENSR alias +
 * LPENSR + RSTCR + CCIPR8 writes were reverted: they regressed the
 * boot to a bare FFFABKCD, so they stay out until proven one at a
 * time.)
 */

if (bus_num == 1)
  {
    modifyreg32(STM32_RCC_AHB5ENR, 0, RCC_AHB5ENR_SDMMC1EN);
  }
else if (bus_num == 2)
  {
    modifyreg32(STM32_RCC_AHB5ENR, 0, RCC_AHB5ENR_SDMMC2EN);
  }

