/**
 * Register-level probe: replicates EXACTLY the NuttX stm32n6_sdmmc.c
 * init sequence (CLKCR=250 -> POWER=3 -> CMD0 -> wait CMDSENT -> CMD8).
 * Goal: run the NuttX sequence inside the VERIFIED bare-metal environment
 * to isolate "NuttX code bug" vs "NuttX environment difference".
 * Triggered by KEY1 (PD1) in the main loop.
 */
static void tfcard_reg_probe(void)
{
  volatile uint32_t *s = (volatile uint32_t *)0x58027000UL;
  uint32_t sta;
  uint32_t i;

  dbg_puts("[P] probe start (same sequence as NuttX sdmmc)\r\n");

  /* CLKCR = CLKDIV 250 (1-bit, no HWFC) */
  s[0x04 >> 2] = 250;
  /* POWER = PWRCTRL ON */
  s[0x00 >> 2] = 3;
  dbg_puts("[P] CLKCR=");
  dbg_print_hex32(s[0x04 >> 2]);
  dbg_puts(" POWER=");
  dbg_print_hex32(s[0x00 >> 2]);
  dbg_puts("\r\n");

  /* wait >74 cycles (loop delay ~5ms@600MHz) */
  for (i = 0; i < 1500000; i++) { }

  /* CMD0: ARG=0, CMD=CPSMEN */
  s[0x08 >> 2] = 0;
  s[0x0C >> 2] = (1u << 12);

  /* wait CMDSENT (bit7) or CTIMEOUT (bit2) */
  sta = 0;
  for (i = 0; i < 5000000; i++)
    {
      sta = s[0x34 >> 2];
      if ((sta & (1u << 7)) || (sta & (1u << 2))) break;
    }
  dbg_puts("[P] after CMD0 STA=");
  dbg_print_hex32(sta);
  dbg_puts("\r\n");

  /* clear static cmd flags if CMDSENT */
  if (sta & (1u << 7))
    {
      s[0x38 >> 2] = 0x8D;   /* CCRCFAIL|CTIMEOUT|CMDREND|CMDSENT */
    }

  /* CMD8: ARG=0x1AA, CMD = index8|WAITRESP_SHORT|CPSMEN */
  s[0x08 >> 2] = 0x1AA;
  s[0x0C >> 2] = 8u | (1u << 8) | (1u << 12);

  /* wait CMDREND/CCRCFAIL and CPSMACT clear (HAL semantics) */
  sta = 0;
  for (i = 0; i < 5000000; i++)
    {
      sta = s[0x34 >> 2];
      if (((sta & 0x45) != 0) && !(sta & (1u << 13))) break;
    }
  dbg_puts("[P] after CMD8 STA=");
  dbg_print_hex32(sta);
  dbg_puts(" RESP1=");
  dbg_print_hex32(s[0x14 >> 2]);
  dbg_puts("\r\n");

  /* restore: POWER=0 to stop, then HAL card again? leave power on, card
   * state is IDLE after CMD0; the app will re-issue CMD0 via HAL later if
   * the user presses KEY0. */
  dbg_puts("[P] probe done\r\n");
}

