 * exact bare-metal [P] sequence.  On success the aligned CCR is kept
 * (it is harmless and matches the golden reference); on failure the
 * original CCR is restored before the normal init continues.
 * =============================================================== */
{
  volatile uint32_t *scb_ccr = (volatile uint32_t *)0xE000ED14UL;
  volatile uint32_t *scb_icia = (volatile uint32_t *)0xE000EF50UL;
  uint32_t ccr_orig = *scb_ccr;
  uint32_t ccr_bm   = 0x00020201UL;    /* bare-metal: IC=1 DC=0 LOB=0 */
  uint32_t ctrl, primask, msp, psp, icsr, sau, sta;
  uint32_t i;

  __asm__ __volatile__ ("mrs %0, CONTROL" : "=r" (ctrl));
  __asm__ __volatile__ ("mrs %0, PRIMASK" : "=r" (primask));
  __asm__ __volatile__ ("mrs %0, MSP" : "=r" (msp));
  __asm__ __volatile__ ("mrs %0, PSP" : "=r" (psp));
  icsr = *(volatile uint32_t *)0xE000ED04UL;
  sau  = *(volatile uint32_t *)0xE000EDD0UL;

  syslog(LOG_INFO,
         "sdmmc: Q1 ENV CTRL=0x%08lx SPSEL=%lu PRIMASK=%lu "
         "MPU_CTRL=0x%08lx CCR=0x%08lx SCTLR=0x%08lx SAU=0x%08lx "
         "ICSR=0x%08lx MSP=0x%08lx PSP=0x%08lx\n",
         (unsigned long)ctrl, (unsigned long)((ctrl >> 1) & 1UL),
         (unsigned long)primask,
         (unsigned long)getreg32(0xE000ED94UL),
         (unsigned long)*scb_ccr,
         (unsigned long)getreg32(0xE000ED00UL + 0x30),
         (unsigned long)sau,
         (unsigned long)icsr,
         (unsigned long)msp,
         (unsigned long)psp);

  /* Snap CCR to the bare-metal value (IC=1, DC=0, LOB=0).  IC enable
   * needs an I-Cache invalidate (ICIALLU @0xE000EF50) + DSB/ISB. */
  *scb_ccr = ccr_bm;
  __asm__ __volatile__ ("isb");
  *scb_icia = 0;      /* ICIALLU */
  __asm__ __volatile__ ("dsb");
  __asm__ __volatile__ ("isb");

  syslog(LOG_INFO,
         "sdmmc: Q1 CCR set 0x%08lx (orig 0x%08lx) -> bare-metal seq\n",
