  sdmmc_putreg(priv, SDMMC_CLKCR_OFFSET, 250);
  sdmmc_putreg(priv, SDMMC_POWER_OFFSET, SDMMC_POWER_PWRCTRL_ON);
  for (i = 0; i < 1500000; i++) { }
  sdmmc_putreg(priv, SDMMC_ARG_OFFSET, 0);
