        }
    }

  syslog(LOG_INFO,
         "sdmmc: Q1 CMD0 STA=0x%08lx %s\n",
         (unsigned long)sta,
         (sta & SDMMC_STA_CMDSENT) ? "SUCCESS" : "FAIL");

  if (sta & SDMMC_STA_CMDSENT)
    {
      /* Aligned CCR worked: keep it (matches golden reference). */
      sdmmc_putreg(priv, SDMMC_ICR_OFFSET, SDMMC_STATIC_CMD_FLAGS);
