  else
    {
      /* Restore original CCR; the normal init path below will retry
       * CMD0 with the original settings (keeps the old diagnostics). */
      *scb_ccr = ccr_orig;
      __asm__ __volatile__ ("dsb");
      __asm__ __volatile__ ("isb");
