/* EARLY UART (USART1 direct register access; the FSBL configures USART1
 * = HSI 115200 before jumping, so this works from __start_c entry). */
static void ep_putc(char c)
{
  volatile uint32_t *isr = (volatile uint32_t *)0x5200101CUL; /* USART1_S ISR */
  volatile uint32_t *tdr = (volatile uint32_t *)0x52001028UL; /* USART1_S TDR */
  while ((*isr & 0x80U) == 0U) { }
  *tdr = (uint32_t)c;
}

static void ep_hex32(uint32_t v)
{
  static const char hex[] = "0123456789ABCDEF";
  int i;
  for (i = 28; i >= 0; i -= 4)
    {
      ep_putc(hex[(v >> i) & 0xF]);
    }
}

static void ep_puts(const char *s)
{
  while (*s) { ep_putc(*s++); }
}

/* GPIO-aware SDMMC early probe (2026-09-09, [E3]).
 *
 * Runs the exact bare-metal tfcard [P] sequence in the __start_c
 * environment AFTER board GPIO init ('B') but BEFORE up_enable_dcache
 * ('K') and the scheduler.  Unlike the removed [E1]/[E2] probes (which
 * ran before the SDMMC GPIO was configured and froze CPSMACT), this
 * probe FIRST configures the SDMMC1 pins (PC8-12=D0-3/CK, PH2=CMD,
 * AF10) and the SDMMC clock, then issues CMD0/CMD8.
 *
 * Purpose: isolate "NuttX boot environment" vs "board_bringup / later
 * environment".  If this probe succeeds while stm32n6_sdmmc_initialize
 * fails, the difference is introduced later (SPSEL=1/PSP, D-Cache
 * enable, scheduler).  If it fails here too, the difference is in the
 * FSBL->NuttX hand-off itself.
 */
static void sdmmc_early_probe_gpio(const char *tag)
{
  volatile uint32_t *s = (volatile uint32_t *)0x58027000UL;
  uint32_t sta = 0;
  uint32_t i;

  ep_puts(tag);

  /* Environment snapshot (compare vs bare-metal tfcard [P] ENV) */
  {
    uint32_t control, primask, mspv, pspv;
    __asm__ __volatile__ ("mrs %0, CONTROL" : "=r" (control));
    __asm__ __volatile__ ("mrs %0, PRIMASK" : "=r" (primask));
    __asm__ __volatile__ ("mrs %0, MSP" : "=r" (mspv));
    __asm__ __volatile__ ("mrs %0, PSP" : "=r" (pspv));
    ep_puts(" ENV CTRL=");
    ep_hex32(control);
    ep_puts(" PRIMASK=");
    ep_hex32(primask);
    ep_puts(" MPU_CTRL=");
    ep_hex32(getreg32(0xE000ED94UL));
    ep_puts(" CCR=");
    ep_hex32(getreg32(0xE000ED14UL));
    ep_puts(" SAU=");
    ep_hex32(getreg32(0xE000EDD0UL));
    ep_puts(" ICSR=");
    ep_hex32(getreg32(0xE000ED04UL));
    ep_puts(" MSP=");
    ep_hex32(mspv);
    ep_puts(" PSP=");
    ep_hex32(pspv);
    ep_puts("\r\n");
  }

  /* Enable SDMMC1 clock (AHB5ENSR set alias, SDMMC1EN=bit8) + HCLK source
   * (CCIPR8 SDMMC1SEL=00), same as the driver does. */
  putreg32(RCC_AHB5ENR_SDMMC1EN, STM32_RCC_BASE + 0x0A60UL); /* AHB5ENSR */
  modifyreg32(STM32_RCC_BASE + 0x160UL, 0x3UL, 0UL); /* CCIPR8 SDMMC1SEL=HCLK */

  /* Configure SDMMC1 GPIO directly (they may not be set up by
   * stm32_boardinitialize yet):
   *   GPIOC = 0x56020800, GPIOH = 0x56021C00 (secure aliases)
   *   PC8-12 = AF10, PH2 = AF10 (see g_sdmmc1_pins in stm32n6_sdmmc.c) */
  modifyreg32(0x56020800UL + 0x00, 0x03FF0000UL, 0x02A80000UL); /* GPIOC MODER */
  modifyreg32(0x56020800UL + 0x24, 0x000FFFFFUL, 0x000AAAAAUL); /* GPIOC AFRH */
  modifyreg32(0x56021C00UL + 0x00, 0x00000030UL, 0x00000020UL); /* GPIOH MODER */
  modifyreg32(0x56021C00UL + 0x20, 0x00000F00UL, 0x00000A00UL); /* GPIOH AFRL */

  /* CLKCR = CLKDIV 250 (1-bit) then POWER ON */
  s[0x04 >> 2] = 250;
  s[0x00 >> 2] = 3;

  /* wait > 74 cycles */
  for (i = 0; i < 1500000; i++) { }

  /* CMD0: ARG=0, CMD=CPSMEN */
  s[0x08 >> 2] = 0;
  s[0x0C >> 2] = (1u << 12);
  sta = 0;
  for (i = 0; i < 5000000; i++)
    {
      sta = s[0x34 >> 2];
      if ((sta & (1u << 7)) || (sta & (1u << 2))) break;
    }

  ep_puts(" S0=");
  ep_hex32(sta);

  if (sta & (1u << 7))
    {
      s[0x38 >> 2] = 0x8D;
    }

  /* CMD8: ARG=0x1AA, CMD = index8 | WAITRESP_SHORT | CPSMEN */
  s[0x08 >> 2] = 0x1AA;
  s[0x0C >> 2] = 8u | (1u << 8) | (1u << 12);
  sta = 0;
  for (i = 0; i < 5000000; i++)
    {
      sta = s[0x34 >> 2];
      if (((sta & 0x45) != 0) && !(sta & (1u << 13))) break;
    }

  ep_puts(" S8=");
  ep_hex32(sta);
  ep_puts(" R1=");
  ep_hex32(s[0x14 >> 2]);
  ep_putc('\r');
  ep_putc('\n');

  /* stop the block (power off) to not disturb later init */
  s[0x00 >> 2] = 0;
}

